css:
:where(.wtyg-map-holiday_culprits){--deep:#0d1a24;--panel:#132430;--line:#24404f;--bone:#dfe6e4;--mist:#93a9b0;--ring:#cfe3e6;--link:#8fc3d6}
:where(.wtyg-map-holiday_culprits) *{box-sizing:border-box;margin:0;padding:0}
:where(.wtyg-map-holiday_culprits) .yr{font-family:Spectral,Georgia,serif;font-size:19px;font-weight:600;text-align:right}
:where(.wtyg-map-holiday_culprits) .nm{font-weight:500}
:where(.wtyg-map-holiday_culprits) .hd{color:var(--mist);font-size:13px}
:where(.wtyg-map-holiday_culprits) .s-hol{font-family:Spectral,Georgia,serif;font-style:italic;font-size:24px;line-height:1.2;margin:18px 0 4px}
:where(.wtyg-map-holiday_culprits) .s-when{font-size:13px;color:var(--mist)}
:where(.wtyg-map-holiday_culprits) .s-name{font-weight:600;margin-top:2px}
:where(.wtyg-map-holiday_culprits) .s-text{font-family:Spectral,Georgia,serif;font-size:16.5px;line-height:1.65;margin:16px 0 18px;max-width:62ch}
:where(.wtyg-map-holiday_culprits) .s-rec{border-top:1px solid var(--line);padding-top:12px}
:where(.wtyg-map-holiday_culprits) .s-rec h3{font-size:12.5px;font-weight:600;color:var(--mist);margin-bottom:6px}
:where(.wtyg-map-holiday_culprits) .s-rec dl{display:grid;grid-template-columns:auto 1fr;gap:4px 12px;font-size:13px}
:where(.wtyg-map-holiday_culprits) .s-rec dt{color:var(--mist)}
:where(.wtyg-map-holiday_culprits) .s-rec a{color:var(--link);word-break:break-all}
:where(.wtyg-map-holiday_culprits) .orb{border-radius:50%;background:var(--c);box-shadow:0 0 0 1.5px rgba(8,16,24,.75),0 0 10px 3px var(--g)}
:where(.wtyg-map-holiday_culprits) .orb.on{box-shadow:0 0 0 2px var(--ring),0 0 16px 6px var(--g)}
:where(.wtyg-map-holiday_culprits) .leaflet-tooltip.tip{background:var(--panel);color:var(--bone);border:1px solid var(--line);border-radius:5px;font-size:13px;box-shadow:none}
:where(.wtyg-map-holiday_culprits) .leaflet-tooltip.tip:before{display:none}:where(.wtyg-map-holiday_culprits) .hol-pop .leaflet-popup-content-wrapper,:where(.wtyg-map-holiday_culprits) .hol-pop .leaflet-popup-tip{background:var(--panel);color:var(--bone);border:1px solid var(--line)}:where(.wtyg-map-holiday_culprits) .hol-story{font-family:Figtree,system-ui,-apple-system,"Segoe UI",sans-serif;font-size:15px;line-height:1.45;color:var(--bone)}:where(.wtyg-map-holiday_culprits) .hol-story .s-hol{margin-top:2px}
